WITH flattened AS (SELECT id, service, host, log_ts, latency_ms, status_code, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, v), flattened_attrs AS (SELECT log_ts, latency_ms, status_code, v, CAST((status_code & 1) != 0 AS INT) AS is_flagged, SHIFTRIGHT(status_code, 2) AS status_code_high FROM flattened), scored AS (SELECT *, AVG(latency_ms) OVER (ORDER BY CAST(log_ts AS BIGINT) ASC RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS latency_ms_avg_1h FROM flattened_attrs WHERE log_ts < '2025-07-31'), cleaned AS (SELECT log_ts, status_code, is_flagged, latency_ms_avg_1h, latency_ms_avg_1h + status_code_high AS latency_ms_avg_1h_plus_status_code_high FROM scored WHERE TO_DATE(log_ts) >= '2023-11-01'), scored_app_logs AS (SELECT *, RANK() OVER (ORDER BY is_flagged DESC NULLS LAST) AS is_flagged_rank, RANK() OVER (ORDER BY status_code ASC) AS status_code_rank, SUM(status_code) OVER (ORDER BY CAST(log_ts AS BIGINT) ASC RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS status_code_sum_1h, PERCENT_RANK() OVER (ORDER BY latency_ms_avg_1h DESC NULLS LAST) AS latency_ms_avg_1h_percent_rank FROM cleaned), report AS (SELECT log_ts, latency_ms_avg_1h, status_code_rank, status_code_sum_1h FROM scored_app_logs ORDER BY latency_ms_avg_1h ASC NULLS LAST) SELECT log_ts, latency_ms_avg_1h, status_code_rank, status_code_sum_1h FROM report
